def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """Count numbers in [low, high] with balanced even/odd digits divisible by k."""
    def up_to(bound: int) -> int:
        if bound <= 0:
            return 0
        digits = tuple(map(int, str(bound)))

        @lru_cache(None)
        def dp(pos: int, tight: bool, started: bool, balance: int, remainder: int) -> int:
            if pos == len(digits):
                return int(started and balance == 0 and remainder == 0)
            maximum = digits[pos] if tight else 9
            total = 0
            for digit in range(maximum + 1):
                next_tight = tight and digit == maximum
                if not started and digit == 0:
                    total += dp(pos + 1, next_tight, False, balance, remainder)
                else:
                    next_balance = balance + (1 if digit % 2 == 0 else -1)
                    total += dp(pos + 1, next_tight, True, next_balance,
                               (remainder * 10 + digit) % k)
            return total

        return dp(0, True, False, 0, 0)

    return up_to(high) - up_to(low - 1)
